do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(ticker,name,segment,size_tier,is_seed,is_hero) values ($q$UBER$q$,$q$Uber Technologies$q$,$q$consumer$q$,$q$large$q$,true,true),($q$AAPL$q$,$q$Apple$q$,$q$consumer$q$,$q$large$q$,true,false),($q$META$q$,$q$Meta Platforms$q$,$q$consumer$q$,$q$large$q$,true,false),($q$MSFT$q$,$q$Microsoft$q$,$q$business$q$,$q$large$q$,true,false),($q$PLTR$q$,$q$Palantir Technologies$q$,$q$business$q$,$q$large$q$,true,false),($q$NVDA$q$,$q$NVIDIA$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$TSM$q$,$q$Taiwan Semiconductor Manufacturing$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$AMD$q$,$q$Advanced Micro Devices$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$DASH$q$,$q$DoorDash$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$NET$q$,$q$Cloudflare$q$,$q$business$q$,$q$mid$q$,true,false),($q$CRWV$q$,$q$CoreWeave$q$,$q$infrastructure$q$,$q$mid$q$,true,true),($q$CBRS$q$,$q$Cerebras Systems$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$NBIS$q$,$q$Nebius Group$q$,$q$infrastructure$q$,$q$mid$q$,true,false),($q$LYFT$q$,$q$Lyft$q$,$q$consumer$q$,$q$small$q$,true,true),($q$APLD$q$,$q$Applied Digital$q$,$q$infrastructure$q$,$q$small$q$,true,false),($q$AMZN$q$,$q$Amazon$q$,$q$consumer$q$,$q$large$q$,true,false),($q$GOOGL$q$,$q$Alphabet$q$,$q$consumer$q$,$q$large$q$,true,false),($q$TSLA$q$,$q$Tesla$q$,$q$consumer$q$,$q$large$q$,true,false),($q$ORCL$q$,$q$Oracle$q$,$q$business$q$,$q$large$q$,true,false),($q$INTC$q$,$q$Intel$q$,$q$infrastructure$q$,$q$large$q$,true,false),($q$LCID$q$,$q$Lucid$q$,$q$consumer$q$,$q$small$q$,true,false),($q$LIME$q$,$q$Lime$q$,$q$consumer$q$,$q$small$q$,true,false),($q$CART$q$,$q$Instacart$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$GRAB$q$,$q$Grab$q$,$q$consumer$q$,$q$mid$q$,true,false),($q$AUR$q$,$q$Aurora$q$,$q$business$q$,$q$small$q$,true,false) on conflict (ticker) do update set is_seed=true, segment=excluded.segment, size_tier=excluded.size_tier, is_hero=excluded.is_hero;
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Ambarella$q$,$q$public_company$q$),($q$Baidu$q$,$q$public_company$q$),($q$Broadcom$q$,$q$public_company$q$),($q$Fabrinet$q$,$q$public_company$q$),($q$Hewlett Packard Enterprise$q$,$q$public_company$q$),($q$Hon Hai$q$,$q$public_company$q$),($q$Lumentum$q$,$q$public_company$q$),($q$Marvell$q$,$q$public_company$q$),($q$Mellanox$q$,$q$private_company$q$),($q$Micron$q$,$q$public_company$q$),($q$OpenAI$q$,$q$private_company$q$),($q$Qualcomm$q$,$q$public_company$q$),($q$SK Hynix$q$,$q$public_company$q$),($q$Samsung$q$,$q$public_company$q$),($q$Wistron$q$,$q$public_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Our acquisition of Mellanox in 2020 expanded our offerings to include networking, enabled our platforms to be data center scale, and led to the introduction of a new processor class – the data processing unit, or DPU.$q$),(2,$q$Our current competitors include:$q$),(3,$q$Regulators in China have inquired about our sales and efforts to supply the China market and our fulfillment of the commitments we entered at the close of our Mellanox acquisition.$q$),(4,$q$The change in Other income, net, compared to fiscal year 2025, was primarily driven by unrealized gains in non-marketable and publicly-held equity securities, including gains from our previously announced investment in Intel’s common stock.$q$),(5,$q$We are finalizing an investment and partnership agreement with OpenAI.$q$),(6,$q$We engage with independent subcontractors and contract manufacturers such as Hon Hai Precision Industry Co., Ltd., Wistron Corporation, and Fabrinet to perform assembly, testing and packaging of our final products.$q$),(7,$q$We purchase memory from SK Hynix Inc., Micron Technology, Inc., and Samsung.$q$),(8,$q$We utilize foundries, such as Taiwan Semiconductor Manufacturing Company Limited, or TSMC, and Samsung Electronics Co., Ltd., or Samsung, to produce our semiconductor wafers.$q$),(9,$q$We utilize foundries, such as Taiwan Semiconductor Manufacturing Company Limited, or TSMC, and Samsung Electronics Co., Ltd., or Samsung, to produce our semiconductor wafers. We purchase memory from SK Hynix Inc., Micron Technology, Inc., and Samsung.$q$),(10,$q$large cloud services companies with internal teams designing hardware and software that incorporate accelerated or AI computing functionality as part of their internal solutions or platforms, such as Alibaba Group, Alphabet Inc., Amazon, Inc., or Amazon, Baidu, Inc., Huawei, and Microsoft Corporation, or Microsoft;$q$),(11,$q$networking products consisting of switches, network adapters (including DPUs), and cable solutions (including optical modules) include such as AMD, Arista Networks, Broadcom, Cisco Systems, Inc., Hewlett Packard Enterprise Company, Huawei, Intel, Lumentum Holdings Inc., and Marvell Technology, Inc, as well as internal teams of system vendors and large cloud services companies.$q$),(12,$q$suppliers of hardware and software for SoC products that are used in servers or embedded into automobiles, autonomous machines, and gaming devices, such as Ambarella, Inc., AMD, Broadcom, Intel, Qualcomm Incorporated, Renesas Electronics Corporation, and Samsung, or companies with internal teams designing SoC products for their own products and services, such as Tesla, Inc.;$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$supplies$q$,$q$TSMC$q$,$q$NVDA$q$,$q${8}$q$::int[],$q${business}$q$::text[],null,null,null,null),(2,$q$supplies$q$,$q$Samsung$q$,$q$NVDA$q$,$q${9}$q$::int[],$q${business}$q$::text[],null,null,null,null),(3,$q$supplies$q$,$q$SK Hynix$q$,$q$NVDA$q$,$q${7}$q$::int[],$q${business}$q$::text[],null,null,null,null),(4,$q$supplies$q$,$q$Micron$q$,$q$NVDA$q$,$q${7}$q$::int[],$q${business}$q$::text[],null,null,null,null),(5,$q$supplies$q$,$q$Hon Hai$q$,$q$NVDA$q$,$q${6}$q$::int[],$q${business}$q$::text[],null,null,null,null),(6,$q$supplies$q$,$q$Wistron$q$,$q$NVDA$q$,$q${6}$q$::int[],$q${business}$q$::text[],null,null,null,null),(7,$q$supplies$q$,$q$Fabrinet$q$,$q$NVDA$q$,$q${6}$q$::int[],$q${business}$q$::text[],null,null,null,null),(8,$q$acquires$q$,$q$NVDA$q$,$q$Mellanox$q$,$q${1,3}$q$::int[],$q${business,risk_factors}$q$::text[],null,null,null,null),(9,$q$competes$q$,$q$NVDA$q$,$q$Baidu$q$,$q${2,10}$q$::int[],$q${business,business}$q$::text[],null,null,null,null),(10,$q$competes$q$,$q$NVDA$q$,$q$Microsoft$q$,$q${2,10}$q$::int[],$q${business,business}$q$::text[],null,null,null,null),(11,$q$competes$q$,$q$NVDA$q$,$q$Ambarella$q$,$q${2,12}$q$::int[],$q${business,business}$q$::text[],null,null,null,null),(12,$q$competes$q$,$q$NVDA$q$,$q$Broadcom$q$,$q${2,12}$q$::int[],$q${business,business}$q$::text[],null,null,null,null),(13,$q$competes$q$,$q$NVDA$q$,$q$Qualcomm$q$,$q${2,12}$q$::int[],$q${business,business}$q$::text[],null,null,null,null),(14,$q$competes$q$,$q$NVDA$q$,$q$Hewlett Packard Enterprise$q$,$q${11}$q$::int[],$q${business}$q$::text[],null,null,null,null),(15,$q$competes$q$,$q$NVDA$q$,$q$Lumentum$q$,$q${11}$q$::int[],$q${business}$q$::text[],null,null,null,null),(16,$q$competes$q$,$q$NVDA$q$,$q$Marvell$q$,$q${11}$q$::int[],$q${business}$q$::text[],null,null,null,null),(17,$q$partners$q$,$q$NVDA$q$,$q$OpenAI$q$,$q${5}$q$::int[],$q${risk_factors}$q$::text[],null,null,null,null),(18,$q$invests$q$,$q$NVDA$q$,$q$Intel$q$,$q${4}$q$::int[],$q${mdna}$q$::text[],null,null,null,null);
create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$NVDA$q$ then ticker=$q$NVDA$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$NVDA M6 group 1$q$,'claude-sonnet-5-5',171533,7877,0.5802,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/1045810/000104581026000021/nvda-20260125.htm$q$,r.sec[k],t,true,$q$2026-02-25$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;